using System;
using System.IO;
using System.Text.Json;
using Exoduser.UnityPort.Core;
class Program
{
 static int count;static void Check(bool value,string name){count++;if(!value)throw new Exception(name);}
 static void Main(string[] args){var f=new LobbyFlow();Check(f.Page==LobbyPage.Title,"startup title");Check(!f.PreviewCharacter,"no fake saved character");f.EnterGate();Check(f.Page==LobbyPage.WorldIntro,"인장 ENTER는 옛 문 없이 현행 세계관 인트로로 직결");f.EnterGate();Check(f.Page==LobbyPage.WorldIntro,"ENTER 중복 입력은 인트로를 재시작하지 않음");f.FinishIntro();Check(f.Page==LobbyPage.Lobby,"finish lobby");f.Replay();Check(f.Page==LobbyPage.Title,"replay reset");f.EnterGate();f.TickGate(1,7.96,false,8);Check(f.Page==LobbyPage.WorldIntro,"source near-end .05 threshold");f.HoldSkip(true,4.999);Check(f.Page==LobbyPage.WorldIntro,"skip requires five seconds");f.HoldSkip(false,1);Check(f.SkipProgress==0,"release resets hold");f.HoldSkip(true,5);Check(f.Page==LobbyPage.Lobby,"hold skip finish");Check(!f.EnterTest(),"cannot enter test without explicit card");f.SelectPreview();Check(f.EnterTest()&&f.Page==LobbyPage.Playing,"explicit temporary test entry");f.ShowLobby();Check(f.Page==LobbyPage.Lobby,"return lobby");f.Replay();f.EnterGate();f.TickGate(15.01,3,false,100);Check(f.Page==LobbyPage.WorldIntro,"15s final safeguard");
 using(var doc=JsonDocument.Parse(File.ReadAllText(args[1]))){var cuts=doc.RootElement.GetProperty("cuts");Check(cuts.GetArrayLength()==LobbyFlow.WorldCuts.Length,"source cut count");for(int i=0;i<LobbyFlow.WorldCuts.Length;i++)Check(Math.Abs(cuts[i].GetDouble()-LobbyFlow.WorldCuts[i])<.000001,"cut source value "+i);for(int i=0;i<LobbyFlow.WorldCuts.Length-1;i++){double next=f.NextCut(LobbyFlow.WorldCuts[i]);Check(Math.Abs(next-LobbyFlow.WorldCuts[i+1])<.000001,"next source cut "+i);}Check(f.NextCut(999)<0,"last cut completion");}
 var watchdog=new FdgPlaybackWatchdog();Check(!watchdog.Tick(0,.1,false,false),"prepared FDG begins");Check(!watchdog.Tick(11.999,.1,false,false)&&!watchdog.FallingBack,"prepared stall retains twelve-second budget");Check(!watchdog.Tick(12,.1,false,false)&&watchdog.FallingBack,"prepared stalled time triggers fallback");Check(!watchdog.Tick(15.19,.1,false,false),"fallback emblem retains 3.2seconds");Check(watchdog.Tick(15.21,.1,false,false),"prepared stalled decoder leaves FDG");watchdog.Reset();Check(!watchdog.Tick(0,0,false,false),"unprepared starts watchdog");Check(!watchdog.Tick(11,1,false,false),"timeupdate resets watchdog");Check(!watchdog.Tick(22.9,1,false,false)&&!watchdog.FallingBack,"progress extends active deadline");Check(!watchdog.Tick(23.01,1,false,false)&&watchdog.FallingBack,"later no-progress triggers fallback");watchdog.Reset();Check(!watchdog.Tick(0,0,true,false)&&watchdog.FallingBack,"decoder error begins fallback immediately");Check(watchdog.Tick(3.21,0,true,false),"error fallback completes");watchdog.Reset();Check(watchdog.Tick(.1,3.2,false,false),"original FDG 3.2second limit");Check(watchdog.Tick(.1,0,false,true),"ended FDG advances");
 f.SetMix(double.NaN,-3);Check(f.VoiceGain==1&&f.MusicGain==0,"finite and clamped volume");f.SetMix(2,.22);Check(f.VoiceGain==1&&f.MusicGain==.22,"source default gains");Console.WriteLine("LOBBY PASS "+count);File.WriteAllText(args[0],"{\"passed\":"+count+",\"failed\":0}");}
}
